    {

           using var activity =  StartCallActivity("ToggleForumTopicIsClosedAsync", typeof(ToggleForumTopicIsClosed).FullName ?? "ToggleForumTopicIsClosedAsync");

           try
           {
             return client.ToggleForumTopicIsClosedAsync(chatId, forumTopicId, isClosed);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
